SELECT 'LEIE person' src, l.FIRST_NAME || ' ' || l.LAST_NAME who, l.CITY, l.STATE, TO_VARCHAR(l.EXCLUSION_DATE) d, l.EXCLUSION_TYPE t, l.GENERAL_CATEGORY || ' / ' || COALESCE(l.SPECIALTY,'') extra
FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_HHS_OIG_LEIE l JOIN ao ON UPPER(TRIM(l.FIRST_NAME)) = ao.fn AND UPPER(TRIM(l.LAST_NAME)) = ao.ln
UNION ALL
SELECT 'LEIE npi or org', COALESCE(l.BUSINESS_NAME, l.LAST_NAME), l.CITY, l.STATE, TO_VARCHAR(l.EXCLUSION_DATE), l.EXCLUSION_TYPE, l.NPI
FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_HHS_OIG_LEIE l
WHERE l.NPI IN (SELECT npi FROM np) OR UPPER(TRIM(l.BUSINESS_NAME)) IN (SELECT org FROM og)
UNION ALL
SELECT 'SAM person', s.FIRST_NAME || ' ' || s.LAST_NAME, s.CITY, s.STATE, TO_VARCHAR(s.ACTIVATION_DATE), s.EXCLUSION_TYPE, s.EXCLUDING_AGENCY
FROM LIBRARY_MARTS.PROCUREMENT.PROCUREMENT__FED_SAM_EXCLUSIONS s JOIN ao ON UPPER(TRIM(s.FIRST_NAME)) = ao.fn AND UPPER(TRIM(s.LAST_NAME)) = ao.ln
UNION ALL
SELECT 'SAM org', s.ENTITY_NAME, s.CITY, s.STATE, TO_VARCHAR(s.ACTIVATION_DATE), s.EXCLUSION_TYPE, s.EXCLUDING_AGENCY
FROM LIBRARY_MARTS.PROCUREMENT.PROCUREMENT__FED_SAM_EXCLUSIONS s WHERE UPPER(TRIM(s.ENTITY_NAME)) IN (SELECT org FROM og);

-- S18 MDS harm check: abuse and neglect citations (F600 F602 F607 F609 F610) per home, Reliant vs other Missouri 40%+ schizophrenia homes vs the rest
WITH sz AS (
  SELECT CCN, MAX(OVERALL_PERCENT) pct
  FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_FACILITY_LEVEL_MINIMUM_DATA_SET_FREQUENCY
  WHERE MDS_ITEM_QUESTION_DESCRIPTION LIKE 'I6000:%' AND MDS_ITEM_RESPONSE = 'Yes' GROUP BY 1),
g AS (
  SELECT nh.CMS_CERTIFICATION_NUMBER_CCN ccn,
         CASE WHEN nh.CHAIN_NAME = 'RELIANT CARE MANAGEMENT' THEN 'Reliant' WHEN sz.pct >= 40 THEN 'MO other 40%+' ELSE 'MO rest' END grp
  FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_NURSING_HOME nh LEFT JOIN sz ON sz.CCN = nh.CMS_CERTIFICATION_NUMBER_CCN
  WHERE nh.STATE = 'MO'),
d AS (
  SELECT CMS_CERTIFICATION_NUMBER_CCN ccn, TRY_TO_NUMBER(REGEXP_SUBSTR(DEFICIENCY_TAG_NUMBER, '[0-9]+')) tag, SCOPE_SEVERITY_CODE ss, SURVEY_DATE
  FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_NURSING_HOME_DEFICIENCIES WHERE STATE = 'MO')
SELECT g.grp, COUNT(DISTINCT g.ccn) homes, COUNT(d.ccn) all_citations,
       COUNT_IF(d.tag IN (600, 602, 607, 609, 610)) abuse_neglect_cites,
       COUNT_IF(d.tag IN (600, 602, 607, 609, 610) AND d.ss IN ('G','H','I','J','K','L')) abuse_harm_or_jeopardy,
       COUNT_IF(d.ss IN ('J','K','L')) immediate_jeopardy_all_tags,
       COUNT(DISTINCT IFF(d.tag IN (600, 602, 607, 609, 610), d.ccn, NULL)) homes_with_abuse_cite,
       MIN(d.SURVEY_DATE) s0, MAX(d.SURVEY_DATE) s1
FROM g LEFT JOIN d ON d.ccn = g.ccn
GROUP BY 1 ORDER BY 1;

-- S19 Second-field check on the one exclusion-list hit: OIG row for ALMA INIT vs any NPPES person of that name
SELECT 'LEIE' src, l.FIRST_NAME || ' ' || COALESCE(l.MIDDLE_NAME || ' ', '') || l.LAST_NAME who, l.ADDRESS addr, l.CITY city, l.STATE st, l.ZIP zip,
       l.NPI npi, TO_VARCHAR(l.EXCLUSION_DATE) d, l.EXCLUSION_TYPE || ' / ' || COALESCE(l.GENERAL_CATEGORY, '') || ' / ' || COALESCE(l.SPECIALTY, '') info
FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_HHS_OIG_LEIE l
WHERE UPPER(TRIM(l.LAST_NAME)) = 'INIT'
UNION ALL
SELECT 'NPPES person', n.PROVIDER_FIRST_NAME || ' ' || COALESCE(n.PROVIDER_MIDDLE_NAME || ' ', '') || n.PROVIDER_LAST_NAME_LEGAL_NAME,
       n.PROVIDER_FIRST_LINE_BUSINESS_PRACTICE_LOCATION_ADDRESS, n.PROVIDER_BUSINESS_PRACTICE_LOCATION_ADDRESS_CITY_NAME,
       n.PROVIDER_BUSINESS_PRACTICE_LOCATION_ADDRESS_STATE_NAME, n.PROVIDER_BUSINESS_PRACTICE_LOCATION_ADDRESS_POSTAL_CODE, n.NPI,
       TO_VARCHAR(n.PROVIDER_ENUMERATION_DATE), COALESCE(n.PROVIDER_CREDENTIAL_TEXT, '') || ' / ' || COALESCE(n.HEALTHCARE_PROVIDER_TAXONOMY_CODE_1, '')
FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_NPPES n
WHERE n.ENTITY_TYPE_CODE = '1' AND UPPER(TRIM(n.PROVIDER_LAST_NAME_LEGAL_NAME)) = 'INIT' AND UPPER(TRIM(n.PROVIDER_FIRST_NAME)) = 'ALMA'
UNION ALL
SELECT 'NPPES hospice org', n.PROVIDER_ORGANIZATION_NAME_LEGAL_BUSINESS_NAME, n.PROVIDER_FIRST_LINE_BUSINESS_PRACTICE_LOCATION_ADDRESS,
       n.PROVIDER_BUSINESS_PRACTICE_LOCATION_ADDRESS_CITY_NAME, n.PROVIDER_BUSINESS_PRACTICE_LOCATION_ADDRESS_STATE_NAME,
       n.PROVIDER_BUSINESS_PRACTICE_LOCATION_ADDRESS_POSTAL_CODE, n.NPI, TO_VARCHAR(n.PROVIDER_ENUMERATION_DATE) || ' upd ' || TO_VARCHAR(n.LAST_UPDATE_DATE),
       n.AUTHORIZED_OFFICIAL_FIRST_NAME || ' ' || n.AUTHORIZED_OFFICIAL_LAST_NAME || ' ' || COALESCE(n.AUTHORIZED_OFFICIAL_TITLE_OR_POSITION, '') || ' ' || COALESCE(n.AUTHORIZED_OFFICIAL_TELEPHONE_NUMBER, '')
FROM LIBRARY_MARTS.HEALTH.HEALTH__FED_CMS_NPPES n
WHERE n.NPI IN ('1922730175', '1558037887');
